module peg_board_checker(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] start_grid,\n    input wire [15:0] target_grid,\n    output reg result,\n    output reg done\n);\n    \n    // State definitions\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] INIT         = 3'd1;\n    localparam [2:0] READ_QUEUE   = 3'd2;\n    localparam [2:0] CHECK_TARGET = 3'd3;\n    localparam [2:0] GEN_NEXT     = 3'd4;\n    localparam [2:0] DONE_STATE   = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // BFS queue and state\n    reg [15:0] queue_mem [0:255]; // 256 entries\n    reg [7:0] rd_ptr, wr_ptr;\n    reg [8:0] queue_count; // count 0-256\n    reg [15:0] current_state;\n    \n    // Visited state array\n    reg [65535:0] visited;\n    \n    // Counters\n    reg [9:0] cycle_count;\n    reg [3:0] bit_counter;\n    \n    // Temporary signals\n    wire queue_empty = (queue_count == 9'd0);\n    wire queue_full  = (queue_count == 9'd256);\n    reg [15:0] next_state_temp;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state         <= IDLE;\n            result        <= 1'b0;\n            done          <= 1'b0;\n            rd_ptr        <= 8'd0;\n            wr_ptr        <= 8'd0;\n            queue_count   <= 9'd0;\n            visited       <= 65536'd0;\n            cycle_count   <= 10'd0;\n            bit_counter   <= 4'd0;\n            current_state <= 16'd0;\n        end else begin\n            // Default assignments\n            done <= 1'b0;\n            \n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    // Clear visited flag and reset pointers\n                    visited         <= 65536'd0;\n                    visited[start_grid] <= 1'b1;\n                    rd_ptr          <= 8'd0;\n                    wr_ptr          <= 8'd0;\n                    queue_mem[0]    <= start_grid;\n                    wr_ptr          <= 8'd1;\n                    queue_count     <= 9'd1;\n                    current_state   <= start_grid;\n                    cycle_count     <= 10'd0;\n                    state           <= READ_QUEUE;\n                end\n                \n                READ_QUEUE: begin\n                    if (queue_empty || (cycle_count >= 10'd1023)) begin\n                        // No solution found\n                        result <= 1'b0;\n                        state  <= DONE_STATE;\n                    end else begin\n                        // Dequeue element\n                        current_state <= queue_mem[rd_ptr];\n                        rd_ptr        <= rd_ptr + 8'd1;\n                        queue_count   <= queue_count - 9'd1;\n                        cycle_count   <= cycle_count + 10'd1;\n                        state         <= CHECK_TARGET;\n                    end\n                end\n                \n                CHECK_TARGET: begin\n                    if (current_state == target_grid) begin\n                        // Solution found\n                        result <= 1'b1;\n                        state  <= DONE_STATE;\n                    end else begin\n                        // Start generating next states\n                        bit_counter <= 4'd0;\n                        state       <= GEN_NEXT;\n                    end\n                end\n                \n                GEN_NEXT: begin\n                    if (bit_counter < 4'd15) begin\n                        bit_counter <= bit_counter + 4'd1;\n                    end\n                    \n                    if (current_state[bit_counter] == 1'b1) begin\n                        next_state_temp = current_state;\n                        next_state_temp[bit_counter] = 1'b0;\n                        \n                        if (!visited[next_state_temp]) begin\n                            // Mark node as visited\n                            visited[next_state_temp] <= 1'b1;\n                            \n                            // Enqueue if not full\n                            if (!queue_full) begin\n                                queue_mem[wr_ptr] <= next_state_temp;\n                                wr_ptr          <= wr_ptr + 8'd1;\n                                queue_count     <= queue_count + 9'd1;\n                            end\n                        end\n                    end\n                    \n                    // Check if last bit processed\n                    if (bit_counter == 4'd15) begin\n                        state <= READ_QUEUE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done  <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule\n